<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';dashboard_headers();shan_dashboard_require_auth();dashboard_require_permission('audit.view');
$before=max(0,(int)($_GET['before'] ?? 0));$q=shan_db()->prepare('SELECT a.*,u.display_name FROM shan_audit a LEFT JOIN shan_users u ON u.id=a.actor_id'.($before?' WHERE a.id<?':'').' ORDER BY a.id DESC LIMIT 50');$q->execute($before?[$before]:[]);$rows=$q->fetchAll();dashboard_head('Activity log');
?><body><?php dashboard_header(shan_config());?><main class="dashboard-main" id="dashboard-content"><section class="dashboard-intro"><div><span class="eyebrow">Administration</span><h1>Activity log</h1><p>Account and submission changes. Passwords and message contents are never recorded here.</p></div></section><section class="review-card"><div class="user-list"><?php foreach($rows as $r):?><article class="user-item"><span><strong><?= dashboard_h($r['display_name'] ?? 'System') ?></strong><small><?= dashboard_h(str_replace(['.','_'],[' · ',' '],$r['action'])) ?></small><small>Reference: <?= dashboard_h($r['target']) ?></small></span><small><?= dashboard_h(dashboard_date($r['created_at'])) ?> PKT</small></article><?php endforeach;?><?php if(!$rows):?><p>No activity yet.</p><?php endif;?></div><?php if(count($rows)===50):?><a class="button button-secondary" href="?before=<?= (int)end($rows)['id'] ?>">Older activity →</a><?php endif;?></section></main></body></html>
